Here's a complete example with both `DataRow` and `DynamicData` approaches:

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;

[TestClass]
public class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // --- DataRow: best for simple inline values ---

    [TestMethod]
    [DataRow(1, 10.00, 10.00)]
    [DataRow(5, 3.50, 17.50)]
    [DataRow(0, 99.99, 0.00)]
    [DataRow(100, 0.01, 1.00)]
    public void CalculateTotal_ReturnsExpected(int quantity, double unitPrice, double expected)
    {
        var result = _calculator.CalculateTotal(quantity, (decimal)unitPrice);
        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(100.00, 0.10, 90.00, DisplayName = "10% off $100")]
    [DataRow(50.00, 0.25, 37.50, DisplayName = "25% off $50")]
    [DataRow(200.00, 0.00, 200.00, DisplayName = "No discount")]
    [DataRow(80.00, 1.00, 0.00, DisplayName = "100% discount")]
    public void ApplyDiscount_ReturnsExpected(double price, double discount, double expected)
    {
        var result = _calculator.ApplyDiscount((decimal)price, (decimal)discount);
        Assert.AreEqual((decimal)expected, result);
    }

    // --- DynamicData: best for complex objects or computed test cases ---

    [TestMethod]
    [DynamicData(nameof(BulkOrderCases), DynamicDataSourceType.Method)]
    public void CalculateTotal_BulkOrders(int quantity, decimal unitPrice, decimal expected)
    {
        var result = _calculator.CalculateTotal(quantity, unitPrice);
        Assert.AreEqual(expected, result);
    }

    private static IEnumerable<object[]> BulkOrderCases()
    {
        yield return new object[] { 1000, 5.99m, 5990.00m };
        yield return new object[] { 250, 12.00m, 3000.00m };
        yield return new object[] { 10000, 0.99m, 9900.00m };
    }

    [TestMethod]
    [DynamicData(nameof(InvalidDiscountCases), DynamicDataSourceType.Property)]
    [ExpectedException(typeof(ArgumentOutOfRangeException))]
    public void ApplyDiscount_InvalidDiscount_Throws(decimal price, decimal discount)
    {
        _calculator.ApplyDiscount(price, discount);
    }

    public static IEnumerable<object[]> InvalidDiscountCases => new[]
    {
        new object[] { 100m, -0.1m },   // negative discount
        new object[] { 100m, 1.5m },    // over 100%
        new object[] { -50m, 0.1m },    // negative price
    };
}
```

**Key best practices shown:**

| Practice | Detail |
|----------|--------|
| `DataRow` | Use for simple primitives; add `DisplayName` for clarity |
| `DynamicData` (method) | Use `yield return` for generated/complex data |
| `DynamicData` (property) | Use for static fixed sets with `decimal` or object types |
| `[TestInitialize]` | Shared setup avoids repetition |
| Boundary values | Zero, 100%, large quantities covered |
| Error cases | Separate test with `[ExpectedException]` |

> **Note:** `DataRow` doesn't support `decimal` literals directly (they're not compile-time constants), so use `double` params and cast — or switch to `DynamicData` when you need exact `decimal` values.
